SELECT x.tool_name, x.file_path, x.command, x.has_result, x.result_is_error, x.operation FROM (SELECT tu.tool_name, tu.file_path, CASE WHEN tu.tool_name = 'Bash' THEN tu.input ->> 'command' END AS command, (tr.tool_use_id IS NOT NULL) AS has_result, tr.is_error AS result_is_error, tu.operation, tu.created_at, tu.ord FROM tools.uses tu LEFT JOIN tools.results tr ON tr.tool_use_id = tu.id AND tr.created_at <= '2026-09-24 08:22:50.453555+00'::timestamptz WHERE tu.session_id = 1173418 AND tu.created_at <= '2026-09-24 08:22:50.453555+00'::timestamptz ORDER BY tu.created_at DESC, tu.ord DESC LIMIT 200) x ORDER BY x.created_at ASC, x.ord ASC
